mapper.select:
select total, name from ( select count(*) total, o.title name from alarm_info r left join sys_org o on r.org_id = o.id where to_char(r.occur_time,'yyyy-MM') = #{params.currentMonth_} and o.id in
#{id}
group by o.title order by total desc) where rownum < 6

select total, name from ( select count(*) total, a.name from alarm_info r left join asset a on r.asset_id = a.id where a.is_del = 1 and to_char(r.occur_time,'yyyy-MM') = #{params.currentMonth_} and r.org_id in
#{id}
group by a.name order by total desc) where rownum < 6

select total, name from ( select count(*) total, c.name from alarm_info r left join alarm_category c on r.alarm_category = c.id where to_char(r.occur_time,'yyyy-MM') = #{params.currentMonth_} and r.org_id in
#{id}
group by c.name) where rownum < 6 order by total desc

select total, decode(alarm_level, 1, '一级告警', 2, '二级告警', 3, '三级告警', 4, '信息通知', '未知') name from (select count(*) total, r.alarm_level from alarm_info r where to_char(r.occur_time, 'yyyy-MM') = #{params.currentMonth_} and r.org_id in
#{id}
group by r.alarm_level) t

select total, alarm_level name from (select count(*) total, r.alarm_level from alarm_info r where to_char(r.occur_time, 'yyyy-MM-dd') = #{params.today_} and r.org_id in
#{id}
group by r.alarm_level) t order by name

select count(*) total, to_char(r.occur_time,'MM') name from alarm_info r where to_char(r.occur_time,'yyyy') = #{params.year_} and r.org_id in
#{id}
group by to_char(r.occur_time,'MM')

select count(*) total, 'all' name, to_char(occur_time,'yyyy-MM') occurMonth from alarm_info where to_char(occur_time,'yyyy-MM') = #{params.currentMonth_} and org_id in
#{id}
group by to_char(occur_time,'yyyy-MM'), 'all' union all select count(*) total, 'first' name, to_char(occur_time,'yyyy-MM') occurMonth from alarm_info where to_char(occur_time,'yyyy-MM') = #{params.currentMonth_} and alarm_level = 1 and org_id in
#{id}
group by to_char(occur_time,'yyyy-MM'), 'first'

select count(*) total, occur_hour name
from alarm_info
where occur_time = #{params.year_}
and occur_month = #{params.month_}
and occur_day = #{params.day_}
and org_id in

    #{id}

group by occur_hour
order by occur_hour

select t.name, count(t.type) total from asset_hardware_fix f left join asset_hardware_type t on f.hardware_type = t.type left join asset a on f.asset_id = a.id where a.is_del = 1 and regexp_like(to_char(f.fix_time, 'yyyy-MM-dd'), #{params.yearMonth}) and a.org_id in
#{id}
group by t.type, t.name

select total, name from (select (port_in+port_out)/(1024*1024) total, a.name from hour_interfaces i left join asset a on i.asset_id = a.id left join sys_org o on a.org_id = o.id where i.statistics_year = #{params.year_} and i.statistics_month = #{params.month_} and i.statistics_day = #{params.day_} and i.statistics_hour = #{params.hour_} and a.is_del = 1 and a.org_id in
#{id}
order by total desc) t where rownum < 6

select m.name, count(a.desk) total from asset a left join asset_mode m on a.desk = m.code where a.is_del = 1
and a.org_id = #{orgId}
and a.org_id in
#{id}
group by a.desk, m.name

select m.name, count(a.MANUFACTURER_ID) total, m.id from asset a left join asset_manufacturer m on
a.MANUFACTURER_ID =
m.ID
where a.is_del = 1 and m.id is not null and a.desk not like '7%'

    and a.desk = #{desk}


    and a.asset_image = #{assetImage}


    and a.org_id = #{orgId}


    and a.org_id in

        #{id}



    (a.ASSET_SUPPLIER != 'JCCA' or a.ASSET_SUPPLIER is null)

group by m.name, m.id

select a.asset_image name, count(a.asset_image) total from asset a
where a.asset_image is not null and a.is_del = 1

    and a.desk = #{desk}


    and a.org_id = #{orgId}


    and a.manufacturer_id = #{manufacturerId}


    and a.org_id in

        #{id}


group by a.asset_image

select * from (select * from (select a.name assetName, a.ip assetIp, m.name assetModeStr , am.name
assetManufacturer, o.title orgName, a.id
assetId, rownum as rowno,
nvl(c.name, '-') cabinetName,concat(concat(att.start_position, '-'), att.end_position) assetPosition
from asset a
left join asset_mode m on a.desk = m.code
left join ASSET_MANUFACTURER am on a.MANUFACTURER_ID = am.ID
left join sys_org o on a.org_id = o.id
left join asset_attach att on a.id = att.asset_id
left join cabinet c on att.cabinet_id = c.id
where a.is_del = 1

    and a.org_id = #{orgId}


    and a.desk = #{desk}


    and a.asset_image = #{assetImage}


    and a.manufacturer_id = #{manufacturerId}


    and a.name like concat(concat('%',#{assetName}),'%')


    and a.ip = #{assetIp}


    and a.org_id in

        #{id}


) where rownum < #{end}) tt where tt.rowno > #{start} order by tt.assetName asc

select count(*) from asset a
where a.is_del = 1

    and a.org_id = #{orgId}


    and a.desk = #{desk}


    and a.asset_image = #{assetImage}


    and a.manufacturer_id = #{manufacturerId}


    and a.name like concat(concat('%',#{assetName}),'%')


    and a.ip = #{assetIp}


    and a.org_id in

        #{id}
